/// <summary>
/// Starts the sandbox-path inspection and the initial backend readiness
/// probe. Called ONLY from App startup (never the ctor or
/// LoadInitialAsync) so unit tests spin no subprocesses or sockets.
/// Mirrors the proven <see cref="StartBackendMonitoring"/> pattern.
/// </summary>
public void StartBackgroundInspections()
{
    _ = LoadSandboxPathsAsync();
    _ = RefreshBackendStatusAsync();
}

/// <summary>
/// Fires the async sandbox-path inspection without blocking the UI.
/// The nono group calls are subprocesses and must not hold up opening
/// the Settings panel.
/// </summary>

